import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// CASA DOMUS MÓVEIS (casa-dos-moveis) · ofertas de Base Box e Base Baú casal + colchão D33, pedido pelo WhatsApp.
// Copy do cliente; voz o locutor ((arquivo do cliente) = voz-v1.mp3 sem o silêncio morto).
// Tempos = trechos de fala medidos na voz-v2 (speech_regions); a voz entra em LEAD.
// Identidade do site e do logo: preto, vermelho e amarelo, letra pesada e geométrica. Varejo popular, animado.
// Pouco material (2 fotos de produto + logo) → jeito motion: tipografia, preço contando e produto grande.

const { fontFamily: MS } = loadMontserrat("normal", { weights: ["600", "800", "900"], subsets: ["latin", "latin-ext"] });

export const CD_FPS = 30;
const LEAD = 0.1;
export const CD_FRAMES = Math.round(49.4 * CD_FPS);

const BLACK = "#0D0D0D";
const RED = "#E3161D";
const YELLOW = "#FFC400";
const WHITE = "#FFFFFF";
const LIGHT = "#F3F0EA";
const WA = "#25D366";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IO = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IO });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 14, stiffness = 180) =>
  spring({ frame: Math.round((t - a) * CD_FPS), fps: CD_FPS, config: { damping, stiffness } });
const img = (f: string) => staticFile(`casa-dos-moveis/${f}`);

// ───────── texto (entra e fica parado) ─────────
type W = [string, number];
const Words: React.FC<{ t: number; words: W[]; size?: number; color?: string; weight?: number }> = ({ t, words, size = 64, color = WHITE, weight = 800 }) => (
  <div style={{ fontFamily: MS, fontWeight: weight, fontSize: size, lineHeight: 1.1, color, textAlign: "center", whiteSpace: "nowrap" }}>
    {words.map(([w, at], i) => {
      const q = k(t, at, 0.22);
      return <span key={i} style={{ display: "inline-block", margin: "0 0.12em", opacity: q, transform: `translateY(${(1 - q) * 22}px) scale(${0.7 + 0.3 * q})` }}>{w}</span>;
    })}
  </div>
);
const Title: React.FC<{ t: number; at: number; children: React.ReactNode; size?: number; color?: string; spacing?: string }> = ({ t, at, children, size = 110, color = WHITE, spacing = "-0.02em" }) => {
  const s = sp(t, at, 13, 220);
  return (
    <div style={{ fontFamily: MS, fontWeight: 900, fontSize: size, lineHeight: 1.0, letterSpacing: spacing, textAlign: "center", whiteSpace: "nowrap", color,
      opacity: Math.min(1, s * 3), transform: `scale(${1.5 - 0.5 * s})` }}>{children}</div>
  );
};
const Block: React.FC<{ t: number; top: number; at: number; gap?: number; children: React.ReactNode }> = ({ t, top, at, gap = 14, children }) => {
  if (t < at - 0.05) return null;
  return <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>;
};
// selo (faixa) que entra girando e assenta
const Chip: React.FC<{ t: number; at: number; children: React.ReactNode; bg: string; color: string; size?: number; rot?: number; pad?: string }> = ({ t, at, children, bg, color, size = 56, rot = -2, pad = "12px 34px 16px" }) => {
  const s = sp(t, at, 11, 240);
  if (t < at - 0.03) return null;
  return (
    <div style={{ fontFamily: MS, fontWeight: 900, fontSize: size, lineHeight: 1, color, background: bg, padding: pad, borderRadius: 18, whiteSpace: "nowrap",
      opacity: Math.min(1, s * 3), transform: `scale(${1.35 - 0.35 * s}) rotate(${rot + (1 - s) * -8}deg)` }}>{children}</div>
  );
};

// ───────── cena e transições ─────────
type Tr = "none" | "slideL" | "slideUp" | "circle" | "wipe" | "zoom" | "iris" | "band";
const TD = 0.38;
const Scene: React.FC<{ t: number; a: number; b: number; tr: Tr; bg: string; cam?: [number, number]; drift?: number; children: React.ReactNode }> = ({ t, a, b, tr, bg, cam = [1, 1.06], drift = -40, children }) => {
  if (t < a || t > b + TD) return null;
  const q = tr === "none" ? 1 : k(t, a, TD);
  let clip = "none", tf = "", op = 1;
  if (tr === "band") clip = `polygon(0 ${(1 - q) * 100}%, 100% ${(1 - q) * 100 - 20 * (1 - q)}%, 100% 100%, 0 100%)`;
  if (tr === "wipe") clip = `polygon(0 0, ${q * 125}% 0, ${q * 125 - 25}% 100%, 0 100%)`;
  if (tr === "slideL") tf = `translateX(${(1 - q) * 100}%)`;
  if (tr === "slideUp") tf = `translateY(${(1 - q) * 100}%)`;
  if (tr === "zoom") { tf = `scale(${1.3 - 0.3 * q})`; op = Math.min(1, q * 1.7); }
  if (tr === "circle") clip = `circle(${q * 120}% at 50% 50%)`;
  if (tr === "iris") clip = `inset(${(1 - q) * 50}% ${(1 - q) * 50}% round ${(1 - q) * 200}px)`;
  const p = lin(t, a, b + TD);
  const z = Math.max(cam[0] + (cam[1] - cam[0]) * p, 1.006 + (Math.abs(drift * p) * 2) / 1920);
  return (
    <AbsoluteFill style={{ clipPath: clip, transform: tf || undefined, opacity: op, overflow: "hidden", background: bg }}>
      <AbsoluteFill style={{ transform: `translateY(${(drift * p).toFixed(1)}px) scale(${z.toFixed(4)})` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

// câmera por trecho: aproxima no ponto da fala e volta (keys = [tempo, escala])
const Cam: React.FC<{ t: number; keys: [number, number][]; origin: string; children: React.ReactNode }> = ({ t, keys, origin, children }) => {
  let z = keys[0][1];
  for (let i = 1; i < keys.length; i++) z += (keys[i][1] - keys[i - 1][1]) * io(t, keys[i][0], 0.7);
  return <AbsoluteFill style={{ transformOrigin: origin, transform: `scale(${z.toFixed(4)})` }}>{children}</AbsoluteFill>;
};

// ───────── peças ─────────
const brl = (v: number, dec: boolean) => {
  const [i, d] = v.toFixed(2).split(".");
  const int = i.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return dec ? `${int},${d}` : int;
};
// preço grande que conta até o valor (à vista) + parcelas embaixo
const Price: React.FC<{ t: number; at: number; value: number; vistaAt: number; parcAt: number; parc: string; jurosAt: number; tag: string; ink: string; accent: string; sub: string }> = ({ t, at, value, vistaAt, parcAt, parc, jurosAt, tag, ink, accent, sub }) => {
  const s = sp(t, at, 12, 220);
  const v = Math.round(value * k(t, at, 0.9));
  const ps = sp(t, parcAt, 13, 200);
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 30 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 24 }}>
        <div style={{ display: "flex", alignItems: "flex-start", padding: "16px 50px 24px", borderRadius: 36, background: tag, boxShadow: "0 26px 60px rgba(0,0,0,0.28)",
          opacity: Math.min(1, s * 3), transform: `scale(${0.4 + 0.6 * s}) rotate(${(1 - s) * -8}deg)` }}>
          <span style={{ fontFamily: MS, fontWeight: 900, fontSize: 62, color: accent, marginTop: 24, marginRight: 14 }}>R$</span>
          <span style={{ fontFamily: MS, fontWeight: 900, fontSize: 170, lineHeight: 1, color: ink, letterSpacing: "-0.04em", fontVariantNumeric: "tabular-nums" }}>{brl(v, false)}</span>
        </div>
      </div>
      <div style={{ height: 70, display: "flex", alignItems: "center" }}>
        <Chip t={t} at={vistaAt} bg={accent} color={tag} size={52} rot={-3}>À VISTA</Chip>
      </div>
      <div style={{ fontFamily: MS, fontWeight: 800, fontSize: 58, color: sub, whiteSpace: "nowrap", opacity: Math.min(1, ps * 3), transform: `translateY(${(1 - ps) * 40}px)` }}>
        ou 10x de <span style={{ fontWeight: 900 }}>R$ {parc}</span>
      </div>
      <div style={{ height: 80, display: "flex", alignItems: "center" }}>
        <Chip t={t} at={jurosAt} bg={tag} color={accent} size={58} rot={2}>SEM JUROS</Chip>
      </div>
    </div>
  );
};

const Logo: React.FC<{ t: number; at: number; w: number; top: number }> = ({ t, at, w, top }) => {
  const s = sp(t, at, 12, 190);
  return (
    <Img src={img("logo.png")} style={{ position: "absolute", left: (1080 - w) / 2, top, width: w, opacity: Math.min(1, s * 3),
      transform: `scale(${0.3 + 0.7 * s}) rotate(${(1 - s) * -12}deg)` }} />
  );
};

// ícones de traço (vermelho no círculo branco)
const Icon: React.FC<{ kind: "hand" | "truck" | "card"; size: number; t: number; at: number }> = ({ kind, size, t, at }) => {
  const s = sp(t, at, 11, 240);
  const st = { fill: "none", stroke: WHITE, strokeWidth: 6, strokeLinecap: "round", strokeLinejoin: "round" } as const;
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none", transform: `scale(${s}) rotate(${(1 - s) * -30}deg)` }}>
      <circle cx={50} cy={50} r={48} fill={RED} />
      {kind === "hand" && (<>
        <rect x={26} y={30} width={48} height={28} rx={5} {...st} />
        <circle cx={50} cy={44} r={7} {...st} />
        <path d="M22 72 h20 l12 -6 h14" {...st} />
      </>)}
      {kind === "truck" && (<>
        <path d="M18 34 h38 v28 h-38 z" {...st} />
        <path d="M56 42 h14 l10 10 v10 h-24" {...st} />
        <circle cx={32} cy={66} r={6} {...st} /><circle cx={68} cy={66} r={6} {...st} />
      </>)}
      {kind === "card" && (<>
        <rect x={20} y={30} width={60} height={40} rx={6} {...st} />
        <path d="M20 42 h60" {...st} /><path d="M30 60 h14" {...st} />
      </>)}
    </svg>
  );
};
const Perk: React.FC<{ t: number; at: number; kind: "hand" | "truck" | "card"; title: string; sub?: string; subAt?: number }> = ({ t, at, kind, title, sub, subAt = at }) => {
  const s = sp(t, at, 14, 200);
  if (t < at - 0.05) return null;
  return (
    <div style={{ width: 840, display: "flex", alignItems: "center", gap: 34, padding: "32px 44px", borderRadius: 36, background: WHITE, boxSizing: "border-box",
      boxShadow: "0 24px 60px rgba(0,0,0,0.35)", opacity: Math.min(1, s * 3), transform: `translateX(${(1 - s) * 600}px) rotate(${(1 - s) * 6}deg)` }}>
      <Icon kind={kind} size={112} t={t} at={at + 0.08} />
      <div>
        <div style={{ fontFamily: MS, fontWeight: 900, fontSize: 60, lineHeight: 1.05, color: BLACK, whiteSpace: "nowrap" }}>{title}</div>
        {sub && <div style={{ marginTop: 8, fontFamily: MS, fontWeight: 800, fontSize: 40, color: RED, whiteSpace: "nowrap", opacity: k(t, subAt, 0.3) }}>{sub}</div>}
      </div>
    </div>
  );
};

const WaIcon: React.FC<{ size: number; color?: string; bg?: string }> = ({ size, color = WHITE, bg = WA }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none" }}>
    <circle cx={50} cy={50} r={50} fill={bg} />
    <path d="M50 20 a30 30 0 0 0 -26 45 l-4 15 15 -4 a30 30 0 1 0 15 -56 z" fill="none" stroke={color} strokeWidth={6} strokeLinejoin="round" />
    <path d="M39 37 c-2 4 0 11 6 17 s13 8 17 6 l2 -5 -7 -4 -3 3 c-3 -1 -7 -5 -8 -8 l3 -3 -4 -7 z" fill={color} />
  </svg>
);

// ───────── composição ─────────
// v3: voz Roger empolgada (voz-v3-cut.wav, 42,2 s). As cenas foram cronometradas na voz o locutor (voz-v2);
// esta tabela leva o tempo da voz nova ao tempo antigo, trecho de fala por trecho de fala: [novo, antigo].
const MAPA_V3: [number, number][] = [
  [-0.2, -0.2], [0.0, 0.0], [2.14, 2.43], [2.51, 2.98], [4.71, 5.33], [5.41, 6.38],
  [5.81, 6.93], [8.66, 9.98], [8.76, 10.13], [11.29, 13.07], [11.61, 13.17], [15.16, 16.88],
  [15.56, 17.43], [18.68, 20.68], [18.76, 20.8], [21.55, 23.78], [21.94, 23.9], [25.99, 28.67],
  [26.38, 29.41], [27.97, 30.88], [28.08, 31.02], [28.96, 31.91], [29.3, 32.24], [30.27, 33.41], [30.36, 33.6], [31.68, 35.31],
  [32.07, 36.2], [33.64, 37.92], [34.03, 38.47], [34.53, 39.17], [34.79, 39.51], [36.73, 41.9], [36.97, 42.14], [38.66, 44.13],
  [39.04, 44.68], [40.44, 46.0], [40.63, 46.29], [42.22, 48.01], [43.6, 49.4],
];
export const CD3_FRAMES = Math.round(43.6 * CD_FPS);
const paraAntigo = (tn: number) => interpolate(tn, MAPA_V3.map((m) => m[0]), MAPA_V3.map((m) => m[1]));

export const CasaDomusOfertasV3: React.FC = () => {
  const frame = useCurrentFrame();
  return <Corpo t={paraAntigo(frame / CD_FPS - LEAD)} />;
};

// v4: voz Liam eufórica (voz-v4-cut.wav, 44,7 s), mesma ideia da tabela da v3: [novo, antigo].
const MAPA_V4: [number, number][] = [[-0.2, -0.2], [0.0, 0.0], [2.86, 2.43], [3.14, 2.98], [6.53, 6.38], [6.81, 6.93], [9.73, 9.98], [9.88, 10.13], [12.74, 13.07], [13.02, 13.17], [15.61, 15.81], [15.73, 16.01], [16.65, 16.88], [16.93, 17.43], [20.22, 20.68], [20.5, 20.8], [23.55, 23.78], [23.83, 23.9], [26.99, 27.54], [27.15, 27.77], [28.03, 28.67], [28.31, 29.41], [29.83, 30.88], [29.95, 31.02], [30.86, 31.91], [31.08, 32.24], [32.08, 33.41], [32.28, 33.6], [34.23, 35.31], [34.51, 36.2], [36.0, 37.92], [36.28, 38.47], [36.84, 39.17], [37.02, 39.51], [38.97, 41.9], [39.17, 42.14], [40.95, 44.13], [41.23, 44.68], [42.57, 46.0], [42.79, 46.29], [44.68, 48.01], [45.98, 49.4]];
export const CD4_FRAMES = Math.round(45.98 * CD_FPS);
const paraAntigoV4 = (tn: number) => interpolate(tn, MAPA_V4.map((m) => m[0]), MAPA_V4.map((m) => m[1]));

export const CasaDomusOfertasV4: React.FC = () => {
  const frame = useCurrentFrame();
  return <Corpo t={paraAntigoV4(frame / CD_FPS - LEAD)} />;
};

export const CasaDomusOfertas: React.FC = () => {
  const frame = useCurrentFrame();
  return <Corpo t={frame / CD_FPS - LEAD} />;
};

const Corpo: React.FC<{ t: number }> = ({ t }) => {
  return (
    <AbsoluteFill style={{ background: BLACK, overflow: "hidden" }}>
      {/* 1 · Seu quarto merece uma renovação (v2: só tipografia; batidas por palavra e o telhado do logo se desenhando) */}
      <Scene t={t} a={-0.2} b={2.75} tr="none" bg={BLACK} cam={[1.0, 1.0]} drift={0}>
        <Cam t={t} keys={[[-0.2, 1.18], [0.1, 1.0], [0.42, 1.06], [0.95, 1.1], [1.5, 1.0], [2.15, 1.05]]} origin="50% 50%">
          {(() => {
            const slam = (at: number, rot: number) => { const q = sp(t, at, 12, 260); return { opacity: Math.min(1, q * 4), transform: `scale(${2.4 - 1.4 * q}) rotate(${(1 - q) * rot}deg)` }; };
            return (
              <div style={{ position: "absolute", left: 120, right: 120, top: 600, display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
                {t > 0.1 && <div style={{ ...slam(0.15, -10), fontFamily: MS, fontWeight: 900, fontSize: 160, lineHeight: 1, color: WHITE }}>SEU</div>}
                {t > 0.4 && <div style={{ ...slam(0.45, 8), fontFamily: MS, fontWeight: 900, fontSize: 182, lineHeight: 1, color: YELLOW, letterSpacing: "-0.03em" }}>QUARTO</div>}
                <div style={{ marginTop: 30 }}><Words t={t} size={92} words={[["merece", 1.0], ["uma", 1.3]]} /></div>
              </div>
            );
          })()}
          {/* no "renovação" o vermelho abre por cima e a palavra entra letra por letra */}
          {(() => {
            const r = io(t, 1.5, 0.45);
            return <div style={{ position: "absolute", left: 540 - 1300, top: 960 - 1300, width: 2600, height: 2600, borderRadius: 1300, background: RED, transform: `scale(${r})` }} />;
          })()}
          {t > 1.55 && (() => {
            const d = k(t, 1.7, 0.45);
            const bar = k(t, 2.05, 0.35);
            return (
              <div style={{ position: "absolute", left: 120, right: 120, top: 690, display: "flex", flexDirection: "column", alignItems: "center" }}>
                <svg width={800} height={217} viewBox="0 0 700 190" style={{ overflow: "visible" }}>
                  <polyline points="40,170 350,30 660,170" fill="none" stroke={WHITE} strokeWidth={34} strokeLinecap="round" strokeLinejoin="round"
                    strokeDasharray={700} strokeDashoffset={700 * (1 - d)} />
                </svg>
                <div style={{ marginTop: 30, fontFamily: MS, fontWeight: 900, fontSize: 128, lineHeight: 1, color: YELLOW, whiteSpace: "nowrap", letterSpacing: "-0.03em" }}>
                  {"RENOVAÇÃO!".split("").map((ch, i) => {
                    const q = sp(t, 1.6 + i * 0.035, 11, 260);
                    return <span key={i} style={{ display: "inline-block", opacity: Math.min(1, q * 4), transform: `translateY(${(1 - q) * -140}px) scale(${1.6 - 0.6 * q})` }}>{ch}</span>;
                  })}
                </div>
                <div style={{ marginTop: 34, width: 760 * bar, height: 18, borderRadius: 9, background: WHITE }} />
              </div>
            );
          })()}
        </Cam>
      </Scene>

      {/* 2 · E a Casa Domus tá com ofertas imperdíveis */}
      <Scene t={t} a={2.75} b={6.75} tr="slideL" bg={RED} cam={[1.0, 1.08]} drift={-30}>
        {(() => {
          const s = sp(t, 3.05, 13, 190);
          return (
            <div style={{ position: "absolute", left: 140, right: 140, top: 520, height: 340, borderRadius: 48, background: BLACK, boxShadow: "0 40px 90px rgba(0,0,0,0.35)",
              display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, s * 3), transform: `scale(${0.4 + 0.6 * s}) rotate(${(1 - s) * -10}deg)` }}>
              <Img src={img("logo.png")} style={{ width: 680 }} />
            </div>
          );
        })()}
        <Block t={t} top={1060} at={4.3} gap={34}>
          <Words t={t} size={64} words={[["tá", 4.3], ["com", 4.45]]} />
          <Title t={t} at={4.6} size={160}>OFERTAS</Title>
          <Chip t={t} at={5.35} bg={YELLOW} color={BLACK} size={84} rot={-4} pad="18px 40px 22px">IMPERDÍVEIS!</Chip>
        </Block>
      </Scene>

      {/* 3 · Base Box Casal + Colchão D33 · R$ 998 à vista ou 10x de R$ 110,89 sem juros */}
      <Scene t={t} a={6.75} b={16.95} tr="circle" bg={LIGHT} cam={[1.0, 1.02]} drift={-20}>
        <Cam t={t} keys={[[6.75, 1], [12.3, 1.06], [13.1, 1.0], [15.9, 1.06]]} origin="50% 60%">
        <Block t={t} top={170} at={6.95} gap={22}>
          <Title t={t} at={6.95} size={88} color={BLACK}>BASE BOX CASAL</Title>
          <Chip t={t} at={8.2} bg={RED} color={WHITE} size={54} rot={-2}>+ COLCHÃO D33</Chip>
        </Block>
        {(() => {
          const s = sp(t, 6.85, 15, 160);
          const m = io(t, 10.0, 0.6);          // o preço chega: a cama sobe e diminui
          const w = 940 - 180 * m;
          const top = 720 - 300 * m;
          const e = lin(t, 6.85, 17.3);
          return <Img src={img("box.png")} style={{ position: "absolute", left: (1080 - w) / 2, top, width: w, opacity: Math.min(1, s * 3),
            transform: `translateX(${(e - 0.5) * 30}px) scale(${(0.5 + 0.5 * s) * (1.0 + 0.1 * e)}) rotate(${(1 - s) * -8 + (e - 0.5) * 3}deg)`, filter: "drop-shadow(0 34px 44px rgba(0,0,0,0.25))" }} />;
        })()}
        <Block t={t} top={1050} at={10.1} gap={0}>
          <Price t={t} at={10.15} value={998} vistaAt={12.4} parcAt={13.2} parc="110,89" jurosAt={16.02} tag={RED} ink={WHITE} accent={YELLOW} sub={BLACK} />
        </Block>
        </Cam>
      </Scene>

      {/* 4 · Base Baú Casal + Colchão D33 · R$ 1.348 à vista ou 10x de R$ 149,78 sem juros (zoom no baú aberto) */}
      <Scene t={t} a={16.95} b={28.95} tr="wipe" bg={YELLOW} cam={[1.03, 1.0]} drift={20}>
        <Cam t={t} keys={[[16.95, 1], [23.0, 1.06], [23.8, 1.0], [27.7, 1.06]]} origin="50% 60%">
        <Block t={t} top={170} at={17.45} gap={22}>
          <Title t={t} at={17.45} size={88} color={BLACK}>BASE BAÚ CASAL</Title>
          <Chip t={t} at={19.3} bg={BLACK} color={YELLOW} size={54} rot={2}>+ COLCHÃO D33</Chip>
        </Block>
        {(() => {
          const s = sp(t, 17.05, 15, 160);
          const m = io(t, 20.5, 0.6);
          const zin = io(t, 18.0, 0.8) * (1 - io(t, 19.9, 0.6));   // aproxima no baú aberto e volta
          const w = 860 - 200 * m;
          const top = 560 - 150 * m;
          const ox = 0.79, oy = 0.2;
          return (
